import{_ as o,o as t,c as r,a0 as n}from"./chunks/framework.CNoGN0p1.js";const a="/phenoblend/assets/profile_plot_PMID_15948193.BIIaZQbo.svg",c=JSON.parse('{"title":"Phenotype Profile Plot","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/profile.md","filePath":"tutorial/profile.md"}'),s={name:"tutorial/profile.md"};function i(l,e,p,h,m,f){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="phenotype-profile-plot" tabindex="-1">Phenotype Profile Plot <a class="header-anchor" href="#phenotype-profile-plot" aria-label="Permalink to &quot;Phenotype Profile Plot&quot;">​</a></h1><p>Phenotype Profile Plots are spread plots that visualize the organ distribution of features in an individual as compared to the distribution of features in the diseases. The organs correspond to the top-level organ terms in the <a href="https://hpo.jax.org/" target="_blank" rel="noreferrer">Human Phenotype Ontology</a>. For instance, <strong>nervous system</strong> corresponds to <a href="https://hpo.jax.org/browse/term/HP:0000707" target="_blank" rel="noreferrer">Abnormality of the nervous system (HP:0000707)</a> and <strong>endocrine</strong> corresponds to <a href="https://hpo.jax.org/browse/term/HP:0000818" target="_blank" rel="noreferrer">Abnormality of the endocrine system (HP:0000818)</a>.</p><p>Each organ shows bars that correspond to counts</p><ul><li><strong>ppkt</strong>: The count of HPO terms in the phenopacket that represent abnormalities in the corresponding organ</li><li><strong>gene symbol</strong>: The count of HPO terms in the disease model corresponding to the gene symbol that represent abnormalities in the corresponding organ. In the figure shown below, the gene symbols are <em>NF1</em> and <em>PTPN11</em>.</li><li><strong>combination</strong>: The count of HPO terms that are common to both (or all) of the disease models for individual genes. In the figure shown below, the combination is <em>NF1</em>+<em>PTPN11</em>.</li></ul><p>Counts are represented as proportions as a radar plot.</p><figure><img src="'+a+'" alt="Phenotype profile plot for NF1/Noonan syndrome case"><figcaption> Data from Bertola DR, et al. (2005) <a href="https://pubmed.ncbi.nlm.nih.gov/15948193/">Neurofibromatosis-Noonan syndrome: molecular evidence of the concurrence of both disorders in a patient. <em>Am J Med Genet A</em> <strong>136</strong>:242-5</a></figcaption></figure>',6)])])}const g=o(s,[["render",i]]);export{c as __pageData,g as default};
